async function request(url:string,method="GET",body?:unknown){const r=await fetch(url,{method,headers:body?{"Content-Type":"application/json"}:undefined,body:body?JSON.stringify(body):undefined});const d:any=await r.json();if(!r.ok)throw Error(d.error||"Request failed");return d}
function exportFile(name:string,content:string,type="application/json"){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function External({url,children}:{url:string;children:React.ReactNode}){return <a href={url} target="_blank" rel="noopener noreferrer" className="external">{children}<ArrowUpRight size={15}/></a>}
function Empty({text}:{text:string}){return <div className="empty"><span className="empty-icon"><FileText size={22}/></span><p>{text}</p></div>}
function Heading({eyebrow,title,text,children}:{eyebrow:string;title:string;text?:string;children?:React.ReactNode}){return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{text&&<p>{text}</p>}</div>{children}</div>}
function Gate(){return <div className="gate"><LockKeyhole size={26}/><h2>Your journey stays private</h2><p>Sign in once to use your profile, calendar, applications and Bank Statements across Campus to Country.</p><a className="button" href="/login">Sign in <ArrowRight size={16}/></a><a className="text-link" href="/register">Create an account</a></div>}
