 useEffect(()=>{let active=true;(async()=>{try{let d;try{d=await request("/api/v1/auth/me")}catch{await request("/api/v1/auth/refresh","POST",{});d=await request("/api/v1/auth/me")}if(active){setUser(d.user);const saved=await request("/api/v1/records");setRows(saved.rows);if(saved.truncated)notify("Showing the most recent 2,000 records. Export tools need pagination for larger histories.")}}catch{if(active){setUser(null);setRows([])}}finally{if(active)setLoaded(true)}})();try{const data=JSON.parse(localStorage.getItem("ctc-ielts-guest-v1")||"[]");if(Array.isArray(data))setGuest(data.filter(r=>["attempt","study","milestone","question"].includes(r.kind)))}catch{notify("Guest progress could not be read.")}request("/api/v1/content?route="+encodeURIComponent(path)).then(d=>setContent(d.rows)).catch(()=>{});return()=>{active=false}},[]);
 useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(""),6500);return()=>clearTimeout(timer)}},[toast]);
 const save=async(kind:Kind,payload:any,id=crypto.randomUUID())=>{if(!user){if(!["attempt","study","milestone","question"].includes(kind))throw Error("Sign in to save private records");const record={id,kind,payload,created_at:new Date().toISOString()};setGuest(previous=>{const next=[record,...previous.filter(r=>r.id!==id)];localStorage.setItem("ctc-ielts-guest-v1",JSON.stringify(next));return next});notify("Saved to this browser's guest progress");return}const d=await request("/api/v1/records","POST",{id,kind,payload});setRows(previous=>[d.record,...previous.filter(r=>r.id!==id)]);notify("Saved to your workspace")};
