 const result=typingResult(target,input,elapsed);
 useEffect(()=>{if(done&&!saved.current){saved.current=true;store.save("attempt",{skill:"Typing",title:level+" · "+minutes+" minute test",wpm:result.wpm,accuracy:result.accuracy,assessment:"Objective practice"}).catch(e=>store.notify(e.message))}},[done]);
